-- tipo: SQL | Mount de Pessoal em 1 ida (CICLOS,CRS,BENEFICIOS,ENCARGOS). Param: cicloId (0 = ciclo aberto default).
SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'ANO',t.ANO,'STATUS',t.STATUS,'CRIADO_EM',t.CRIADO_EM,'VERSAO_ATUAL',t.VERSAO_ATUAL,'ULTIMO_MES_REALIZADO',t.ULTIMO_MES_REALIZADO,'VERSAO_CONTROLE',t.VERSAO_CONTROLE,'VERSAO_ORIGEM_ID',t.VERSAO_ORIGEM_ID,'CRIADO_POR',t.CRIADO_POR)) FROM CICLO t WHERE (t.STATUS != 'FECHADO' OR t.VERSAO_ATUAL = 'true')),JSON_ARRAY()) AS CICLOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'CODIGO',t.CODIGO,'NOME',t.NOME,'EMPRESA_ID',t.EMPRESA_ID,'ATIVO',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = 'true'),JSON_ARRAY()) AS CRS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'TIPO',t.TIPO,'VALOR',t.VALOR,'PERCENTUAL',t.PERCENTUAL,'APLICA_PJ',t.APLICA_PJ,'APLICA_CLT',t.APLICA_CLT,'CICLO_ID',t.CICLO_ID)) FROM BENEFICIO t WHERE t.CICLO_ID = CASE WHEN {{cicloId}} > 0 THEN {{cicloId}} ELSE COALESCE((SELECT ID FROM CICLO WHERE VERSAO_ATUAL = 'true' ORDER BY ID DESC LIMIT 1), (SELECT ID FROM CICLO WHERE STATUS != 'FECHADO' ORDER BY ANO DESC, ID DESC LIMIT 1)) END),JSON_ARRAY()) AS BENEFICIOS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('ID',t.ID,'NOME',t.NOME,'PERCENTUAL',t.PERCENTUAL,'APLICA_PJ',t.APLICA_PJ,'APLICA_CLT',t.APLICA_CLT,'CICLO_ID',t.CICLO_ID)) FROM ENCARGO t WHERE t.CICLO_ID = CASE WHEN {{cicloId}} > 0 THEN {{cicloId}} ELSE COALESCE((SELECT ID FROM CICLO WHERE VERSAO_ATUAL = 'true' ORDER BY ID DESC LIMIT 1), (SELECT ID FROM CICLO WHERE STATUS != 'FECHADO' ORDER BY ANO DESC, ID DESC LIMIT 1)) END),JSON_ARRAY()) AS ENCARGOS